@flask_app.template_filter('money')
def format_money(value):
    """Р В Р’В¤Р В РЎвЂўР РЋР вЂљР В РЎВР В Р’В°Р РЋРІР‚С™ Р РЋРІР‚РЋР В РЎвЂР РЋР С“Р В Р’В»Р В Р’В°: 1 234.56 Р Р†РІР‚В РІР‚в„ў '1 234.56'"""
    if value is None or value == 0:
        return '0'
    try:
        return f'{value:,.2f}'.replace(',', ' ')
    except (ValueError, TypeError):
        return str(value)


