# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Trade API (from QUIK) Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ

@flask_app.route('/api/trade', methods=['POST'])
def api_trade():
    """Receive trades from QUIK OnAllTrade callback.

    JSON body (batch):
        {"trades": [
            {"trade_num": 123, "sec_code": "SBER", "class_code": "TQBR",
             "price": 312.5, "qty": 100, "value": 31250.0, ...}
        ]}
    """
    data = request.get_json(silent=True)
    if not data or 'trades' not in data or not isinstance(data['trades'], list):
        return jsonify({'error': 'Invalid JSON, expected {"trades": [...]}'}), 400

    if not data['trades']:
        return jsonify({'error': 'Empty trades list'}), 400

    save_quik_trades(data['trades'])

    # Р В РЎСљР В РІР‚Сћ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР В Р’В·Р В Р’В°Р В РЎвЂ”Р В РЎвЂР РЋР С“Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР В РЎВ current_price Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В РЎвЂўР В РІвЂћвЂ“ Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂќР В РЎвЂ: Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В Р’В° Р В РЎвЂ”Р В РЎвЂўР В РЎвЂќР РЋРЎвЂњР В РЎвЂ”Р В РЎвЂќР В РЎвЂ/Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В РўвЂР В Р’В°Р В Р’В¶Р В РЎвЂ Р Р†Р вЂљРІР‚Сњ
    # Р РЋР РЉР РЋРІР‚С™Р В РЎвЂў Р В Р вЂ¦Р В Р’Вµ Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋРЎвЂњР РЋРІР‚В°Р В Р’В°Р РЋР РЏ Р РЋР вЂљР РЋРІР‚в„–Р В Р вЂ¦Р В РЎвЂўР РЋРІР‚РЋР В Р вЂ¦Р В Р’В°Р РЋР РЏ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В Р’В° (Р В РЎвЂўР РЋР С“Р В РЎвЂўР В Р’В±Р В Р’ВµР В Р вЂ¦Р В Р вЂ¦Р В РЎвЂў Р В РўвЂР В Р’В»Р РЋР РЏ Р РЋРІР‚С›Р РЋР Р‰Р РЋР вЂ№Р РЋРІР‚РЋР В Р’ВµР РЋР вЂљР РЋР С“Р В РЎвЂўР В Р вЂ  SPBFUT, Р В РЎвЂ“Р В РўвЂР В Р’Вµ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В Р’В°
    # Р В РЎвЂќР В РЎвЂўР В Р вЂ¦Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р В РЎвЂќР РЋРІР‚С™Р В Р’В° Р В РЎвЂўР РЋРІР‚С™Р В Р’В»Р В РЎвЂР РЋРІР‚РЋР В Р’В°Р В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ). Р В Р’В Р РЋРІР‚в„–Р В Р вЂ¦Р В РЎвЂўР РЋРІР‚РЋР В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р РЋРІР‚в„– Р В РЎвЂ”Р РЋР вЂљР В РЎвЂР РЋРІР‚В¦Р В РЎвЂўР В РўвЂР РЋР РЏР РЋРІР‚С™ Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂў Р РЋРІР‚РЋР В Р’ВµР РЋР вЂљР В Р’ВµР В Р’В· /api/price.

    return jsonify({'status': 'ok', 'count': len(data['trades'])}), 200


# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Accounts API (Р РЋР С“Р В РЎвЂ”Р В РЎвЂР РЋР С“Р В РЎвЂўР В РЎвЂќ Р РЋР С“Р РЋРІР‚РЋР В Р’ВµР РЋРІР‚С™Р В РЎвЂўР В Р вЂ  Р В РЎвЂР В Р’В· QUIK) Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ

@flask_app.route('/api/accounts', methods=['GET'])
def api_accounts():
    """Get distinct accounts from QUIK trades (Р В РўвЂР В Р’В»Р РЋР РЏ Р В Р вЂ¦Р В Р’В°Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В РІвЂћвЂ“Р В РЎвЂќР В РЎвЂ ACCOUNT_BROKER_MAP)."""
    from app.db import get_connection
    conn = get_connection()
    rows = conn.execute("""
        SELECT DISTINCT account, broker,
               COUNT(*) AS trade_count,
               MAX(created_at) AS last_seen
        FROM quik_trade
        WHERE account IS NOT NULL AND account != ''
        GROUP BY account, broker
        ORDER BY account
    """).fetchall()
    conn.close()
    return jsonify([dict(r) for r in rows])


# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Detail lots API Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ

@flask_app.route('/api/lots', methods=['GET'])
def api_lots():
    """Р В Р Р‹Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В РЎвЂќР В РЎвЂ Р В Р’В±Р В Р’В»Р В РЎвЂўР В РЎвЂќР В Р’В° Р вЂ™Р’В«Р В РІР‚СњР В Р’ВµР РЋРІР‚С™Р В Р’В°Р В Р’В»Р В РЎвЂР вЂ™Р’В» Р В Р вЂ¦Р В Р’В° Р В РўвЂР В Р’В°Р РЋРІвЂљВ¬Р В Р’В±Р В РЎвЂўР РЋР вЂљР В РўвЂР В Р’Вµ.

    Р В РІР‚С”Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В Р вЂ  Р В Р вЂ¦Р В Р’В°Р В Р’В±Р В РЎвЂР РЋР вЂљР В Р’В°Р РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р РЋРІР‚С™Р РЋРІР‚в„–Р РЋР С“Р РЋР РЏР РЋРІР‚РЋР В РЎвЂ, Р В РЎвЂ Р В Р вЂ  HTML Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚В Р РЋРІР‚в„– Р В РЎвЂўР В Р вЂ¦Р В РЎвЂ Р В РўвЂР В Р’В°Р В Р вЂ Р В Р’В°Р В Р’В»Р В РЎвЂ Р В Р’В±Р В РЎвЂўР В Р’В»Р РЋР Р‰Р РЋРІвЂљВ¬Р В Р’Вµ Р В РўвЂР В Р вЂ Р РЋРЎвЂњР РЋРІР‚В¦
    Р В РЎВР В Р’ВµР В РЎвЂ“Р В Р’В°Р В Р’В±Р В Р’В°Р В РІвЂћвЂ“Р РЋРІР‚С™, Р РЋРІР‚В¦Р В РЎвЂўР РЋРІР‚С™Р РЋР РЏ Р В Р’В±Р В Р’В»Р В РЎвЂўР В РЎвЂќ Р В РЎвЂ”Р В РЎвЂў Р РЋРЎвЂњР В РЎВР В РЎвЂўР В Р’В»Р РЋРІР‚РЋР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋР вЂ№ Р РЋР С“Р В Р вЂ Р РЋРІР‚ВР РЋР вЂљР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™. Р В РЎвЂєР РЋРІР‚С™Р В РўвЂР В Р’В°Р РЋРІР‚ВР В РЎВ Р В РЎвЂР РЋРІР‚В¦ Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂў Р В РЎвЂ
    Р В РЎвЂ”Р В РЎвЂўР В РўвЂР В РЎвЂ“Р РЋР вЂљР РЋРЎвЂњР В Р’В¶Р В Р’В°Р В Р’ВµР В РЎВ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р вЂ Р В РЎвЂўР В РЎВ Р РЋР вЂљР В Р’В°Р РЋР С“Р В РЎвЂќР РЋР вЂљР РЋРІР‚в„–Р РЋРІР‚С™Р В РЎвЂР В РЎвЂ.
    """
    def to_dmy(iso):
        parts = (iso or '').split('-')
        if len(parts) == 3:
            return f'{parts[2]}.{parts[1]}.{parts[0]}'
        return iso or ''

    df_dmy = to_dmy(request.args.get('date_from', ''))
    dt_dmy = to_dmy(request.args.get('date_to', ''))
    broker = request.args.get('broker', 'all')

    lots = get_trade_lots(None, df_dmy, dt_dmy, broker)
    instruments = get_instrument_summary(None, df_dmy, dt_dmy, broker)
    open_codes = set(i['security_code'] for i in instruments) if instruments else set()

    return render_template('_lots_rows.html', lots=lots, open_codes=open_codes)


# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Instruments API Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ

@flask_app.route('/api/instruments', methods=['GET', 'POST'])
def api_instruments():
    if request.method == 'POST':
        """Save instrument reference data (lotsize, min_step, etc.) from QUIK."""
        data = request.get_json(silent=True)
        if not data or 'instruments' not in data or not isinstance(data['instruments'], list):
            return jsonify({'error': 'Invalid JSON, expected {"instruments": [...]}'}), 400
        if not data['instruments']:
            return jsonify({'error': 'Empty instruments list'}), 400
        save_instruments_batch(data['instruments'])
        return jsonify({'status': 'ok', 'count': len(data['instruments'])}), 200

    """Get list of user's instruments (from trade history)."""
    instruments = get_my_instruments()
    return jsonify(instruments), 200


# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Price API Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ

@flask_app.route('/api/price', methods=['POST'])
def api_price():
    """Receive current instrument price from QUIK or other sources.

    JSON body (single):
        {"sec_code": "SBER", "price": 250.12, "qty": 100, "class_code": "TQBR"}

    JSON body (batch):
        {"prices": [
            {"sec_code": "SBER", "price": 250.12, "qty": 100, "class_code": "TQBR"},
            {"sec_code": "GAZP", "price": 150.50, "qty": 50, "class_code": "TQBR"}
        ]}
    """
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    # Batch mode
    if 'prices' in data and isinstance(data['prices'], list):
        if not data['prices']:
            return jsonify({'error': 'Empty prices list'}), 400
        save_prices_batch(data['prices'])
        return jsonify({'status': 'ok', 'count': len(data['prices'])}), 200

    # Single mode
    sec_code = data.get('sec_code')
    price = data.get('price')
    if not sec_code or price is None:
        return jsonify({'error': 'sec_code and price are required'}), 400

    save_price(
        sec_code=sec_code,
        price=float(price),
        qty=int(data.get('qty', 0)),
        value=float(data.get('value', 0)),
        class_code=data.get('class_code', '')
    )
    return jsonify({'status': 'ok', 'sec_code': sec_code, 'price': float(price)}), 200


@flask_app.route('/api/target', methods=['POST'])
def api_target():
    """Р В Р Р‹Р В РЎвЂўР РЋРІР‚В¦Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚С™Р РЋР Р‰ (Р В РЎвЂР В Р’В»Р В РЎвЂ Р РЋР С“Р В Р вЂ¦Р РЋР РЏР РЋРІР‚С™Р РЋР Р‰) Р РЋРІР‚В Р В Р’ВµР В Р’В»Р В Р’ВµР В Р вЂ Р РЋРЎвЂњР РЋР вЂ№ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р РЋРЎвЂњ Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р РЋРЎвЂњ."""
    data = request.get_json(silent=True) or {}
    code = (data.get('sec_code') or '').strip()
    if not code:
        return jsonify({'error': 'sec_code is required'}), 400
    try:
        price = float(data.get('price') or 0)
    except (TypeError, ValueError):
        return jsonify({'error': 'price must be a number'}), 400
    set_price_target(code, price if price > 0 else None)
    return jsonify({'status': 'ok', 'sec_code': code,
                    'price': price if price > 0 else None}), 200


@flask_app.route('/api/manual-flow', methods=['POST'])
def api_manual_flow():
    """Р В РІР‚СњР В РЎвЂўР В Р’В±Р В Р’В°Р В Р вЂ Р В РЎвЂР РЋРІР‚С™Р РЋР Р‰ Р РЋР вЂљР РЋРЎвЂњР РЋРІР‚РЋР В Р вЂ¦Р В РЎвЂўР В РІвЂћвЂ“ Р В РЎвЂ”Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В РЎвЂќ Р В РўвЂР В Р’ВµР В Р вЂ¦Р В Р’ВµР В РЎвЂ“ (Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР В Р вЂ Р В РЎвЂўР В РўвЂ, Р В РЎвЂќР В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂўР В РЎвЂ“Р В РЎвЂў Р В Р вЂ¦Р В Р’ВµР РЋРІР‚С™ Р В Р вЂ  Р В РЎвЂўР РЋРІР‚С™Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™Р В Р’В°Р РЋРІР‚В¦)."""
    data = request.get_json(silent=True) or {}
    day = (data.get('date') or '').strip()
    try:
        amount = float(str(data.get('amount') or '').replace(',', '.').replace(' ', ''))
    except (TypeError, ValueError):
        return jsonify({'error': 'amount must be a number'}), 400
    if len(day) != 10 or day[4] != '-':
        return jsonify({'error': 'date must be YYYY-MM-DD'}), 400
    if not amount:
        return jsonify({'error': 'amount must be non-zero'}), 400
    flow_id = add_manual_flow(day, amount, (data.get('description') or '')[:200])
    return jsonify({'status': 'ok', 'id': flow_id}), 200


@flask_app.route('/api/manual-flow/delete', methods=['POST'])
def api_manual_flow_delete():
    data = request.get_json(silent=True) or {}
    try:
        flow_id = int(data.get('id'))
    except (TypeError, ValueError):
        return jsonify({'error': 'id is required'}), 400
    delete_manual_flow(flow_id)
    return jsonify({'status': 'ok'}), 200


@flask_app.route('/api/prices', methods=['GET'])
def api_prices():
    """Get all current instrument prices (QUIK, Р РЋР С“ Р РЋР вЂљР В Р’ВµР В Р’В·Р В Р’ВµР РЋР вЂљР В Р вЂ Р В РЎвЂўР В РЎВ Р В РЎвЂР В Р’В· T-Invest)."""
    prices, _source = _effective_prices(get_current_prices())
    # Р В Р’ВР В Р’В·Р В РЎВР В Р’ВµР В Р вЂ¦Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’Вµ Р В РЎвЂќ Р В РЎвЂ”Р РЋР вЂљР В Р’ВµР В РўвЂР РЋРІР‚в„–Р В РўвЂР РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР В РЎВР РЋРЎвЂњ Р В РўвЂР В Р вЂ¦Р РЋР вЂ№ Р В Р вЂ¦Р РЋРЎвЂњР В Р’В¶Р В Р вЂ¦Р В РЎвЂў Р РЋРІР‚С™Р В РЎвЂўР В Р’В»Р РЋР Р‰Р В РЎвЂќР В РЎвЂў Р В РЎвЂ”Р В РЎвЂў Р В Р’В±Р РЋРЎвЂњР В РЎВР В Р’В°Р В РЎвЂ“Р В Р’В°Р В РЎВ Р РЋР С“ Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂќР РЋР вЂљР РЋРІР‚в„–Р РЋРІР‚С™Р РЋРІР‚в„–Р В РЎВР В РЎвЂ
    # Р В РЎвЂ”Р В РЎвЂўР В Р’В·Р В РЎвЂР РЋРІР‚В Р В РЎвЂР РЋР РЏР В РЎВР В РЎвЂ: Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂўР РЋР С“Р РЋРІР‚С™Р В Р’В°Р В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В РЎВ Р В РўвЂР В Р вЂ¦Р В Р’ВµР В Р вЂ Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р РЋР С“Р В Р вЂ Р В Р’ВµР РЋРІР‚РЋР В РЎвЂ T-Invest Р В Р вЂ¦Р В Р’Вµ Р В Р’В·Р В Р’В°Р В РЎвЂ”Р РЋР вЂљР В Р’В°Р РЋРІвЂљВ¬Р В РЎвЂР В Р вЂ Р В Р’В°Р В Р’ВµР В РЎВ.
    prev = tinkoff_prices.previous_closes(_TRACKED_INSTRUMENTS)
    for p in prices:
        base = prev.get(p['sec_code'])
        if base:
            p['prev_close'] = base
    return jsonify(prices), 200


