@flask_app.route('/api/quik-connected', methods=['GET'])
def api_quik_connected():
    """Р В РЎСџР В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В РЎвЂќ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦: QUIK Р В Р’В°Р В РЎвЂќР РЋРІР‚С™Р В РЎвЂР В Р вЂ Р В Р’ВµР В Р вЂ¦, Р В Р’В° Р В Р’ВµР РЋР С“Р В Р’В»Р В РЎвЂ Р В Р вЂ¦Р В Р’ВµР РЋРІР‚С™ Р Р†Р вЂљРІР‚Сњ Р В РЎвЂР РЋР С“Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р РЋР Р‰Р В Р’В·Р РЋРЎвЂњР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р РЋР вЂљР В Р’ВµР В Р’В·Р В Р’ВµР РЋР вЂљР В Р вЂ  T-Invest."""
    prices = get_current_prices()
    connected = _prices_are_fresh(prices)
    tinkoff = (not connected and tinkoff_prices.enabled()
               and tinkoff_prices.cached_count() > 0)
    return jsonify({
        'connected': connected,
        'tinkoff': bool(tinkoff),
        'source': 'quik' if connected else ('tinkoff' if tinkoff else 'none'),
    }), 200


@flask_app.route('/api/forecast', methods=['GET'])
def api_forecast():
    """Get forecast P&L for open positions based on current prices.

    Р В Р в‚¬Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р РЋРІР‚С›Р В РЎвЂР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р РЋР вЂљ Р В РЎвЂ”Р В РЎвЂў Р В Р’В±Р РЋР вЂљР В РЎвЂўР В РЎвЂќР В Р’ВµР РЋР вЂљР РЋРЎвЂњ Р В РЎвЂ Р В РўвЂР В Р’В°Р РЋРІР‚С™Р В Р’В°Р В РЎВ (query-Р В РЎвЂ”Р В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР РЋРІР‚в„– broker, date_from,
    date_to), Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂўР В Р’В±Р РЋРІР‚в„– Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В РЎвЂ“Р В Р вЂ¦Р В РЎвЂўР В Р’В· Р В Р вЂ¦Р В Р’В° Р В РўвЂР В Р’В°Р РЋРІвЂљВ¬Р В Р’В±Р В РЎвЂўР РЋР вЂљР В РўвЂР В Р’Вµ Р РЋР С“Р В РЎвЂўР В Р вЂ Р В РЎвЂ”Р В Р’В°Р В РўвЂР В Р’В°Р В Р’В» Р РЋР С“ Р В Р вЂ Р РЋРІР‚в„–Р В Р’В±Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р В РЎВ Р РЋРІР‚С›Р В РЎвЂР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В РЎВ.
    """
    broker = request.args.get('broker', 'all')
    date_from = request.args.get('date_from', '')
    date_to = request.args.get('date_to', '')
    global _TRACKED_INSTRUMENTS

    # Р В РЎв„ўР В РЎвЂўР В Р вЂ¦Р В Р вЂ Р В Р’ВµР РЋР вЂљР РЋРІР‚С™Р В Р’В°Р РЋРІР‚В Р В РЎвЂР РЋР РЏ HTML date (YYYY-MM-DD) Р Р†РІР‚В РІР‚в„ў DD.MM.YYYY Р В РўвЂР В Р’В»Р РЋР РЏ Р В РІР‚ВР В РІР‚Сњ
    def to_dmy(iso):
        if not iso:
            return ''
        parts = iso.split('-')
        if len(parts) == 3:
            return f'{parts[2]}.{parts[1]}.{parts[0]}'
        return iso

    # date_from Р В Р вЂ¦Р В Р’Вµ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР В РўвЂР В Р’В°Р РЋРІР‚ВР В РЎВ Р В Р вЂ  get_open_trades: Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂќР РЋР вЂљР РЋРІР‚в„–Р РЋРІР‚С™Р В Р’В°Р РЋР РЏ Р В РЎвЂ”Р В РЎвЂўР В Р’В·Р В РЎвЂР РЋРІР‚В Р В РЎвЂР РЋР РЏ Р В РЎвЂ”Р В РЎвЂўР В РЎвЂќР В Р’В°Р В Р’В·Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ
    # Р РЋРІР‚В Р В Р’ВµР В Р’В»Р В РЎвЂР В РЎвЂќР В РЎвЂўР В РЎВ, Р В РўвЂР В Р’В°Р В Р’В¶Р В Р’Вµ Р В Р’ВµР РЋР С“Р В Р’В»Р В РЎвЂ Р В Р вЂ¦Р В Р’В°Р В Р’В±Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В Р’В° Р В РўвЂР В РЎвЂў Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’В°Р В Р’В»Р В Р’В° Р РЋРІР‚С›Р В РЎвЂР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р РЋР вЂљР В Р’В° (Р В Р вЂ  Р РЋРІР‚С™Р В Р’В°Р В Р’В±Р В Р’В»Р В РЎвЂР РЋРІР‚В Р В Р’Вµ Р РЋР РЉР РЋРІР‚С™Р В РЎвЂў Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ
    # Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В РЎвЂќР В РЎвЂ Р вЂ™Р’В«Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂќР РЋР вЂљР РЋРІР‚в„–Р РЋРІР‚С™Р В Р’В°Р РЋР РЏР вЂ™Р’В» Р РЋР С“ Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР В РІвЂћвЂ“ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР В РЎвЂўР РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В РЎвЂќР В РЎвЂўР В РІвЂћвЂ“).
    open_trades = list(get_open_trades(None, None, to_dmy(date_to), broker))

    db_prices = get_current_prices()
    quik_connected = _prices_are_fresh(db_prices)
    instruments = {o['security_code']: _TRACKED_INSTRUMENTS.get(o['security_code'], '')
                   for o in open_trades}
    if instruments:
        _TRACKED_INSTRUMENTS = dict(instruments)
    prices, _source = _effective_prices(db_prices, instruments, quik_connected)
    price_map = {p['sec_code']: p['price'] for p in prices}

    TRADE_FEE_RATE = 0.000685
    forecast_map = {}
    if open_trades:
        for o in open_trades:
            code = o['security_code']
            cur = price_map.get(code, 0)
            if cur <= 0:
                # Р В РЎСљР В Р’ВµР РЋРІР‚С™ Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР В РІвЂћвЂ“ Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р РЋРІР‚в„– Р Р†Р вЂљРІР‚Сњ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР В РЎвЂ“Р В Р вЂ¦Р В РЎвЂўР В Р’В· Р В Р вЂ¦Р В Р’Вµ Р РЋР С“Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р В Р’ВµР В РЎВ (Р В РЎвЂР В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’Вµ -Р РЋР С“Р РЋРІР‚С™Р В РЎвЂўР В РЎвЂР В РЎВР В РЎвЂўР РЋР С“Р РЋРІР‚С™Р РЋР Р‰ Р В РЎвЂ”Р В РЎвЂўР В Р’В·Р В РЎвЂР РЋРІР‚В Р В РЎвЂР В РЎвЂ
                # Р В РЎвЂ”Р РЋР вЂљР В Р’ВµР В Р вЂ Р РЋР вЂљР В Р’В°Р РЋРІР‚В°Р В Р’В°Р В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ  Р В Р’В»Р В РЎвЂўР В Р’В¶Р В Р вЂ¦Р РЋРІР‚в„–Р В РІвЂћвЂ“ Р вЂ™Р’В«Р РЋРЎвЂњР В Р’В±Р РЋРІР‚в„–Р РЋРІР‚С™Р В РЎвЂўР В РЎвЂќ -100%Р вЂ™Р’В» Р В РЎвЂ Р РЋР вЂљР В Р’В°Р В Р’В·Р В РўвЂР РЋРЎвЂњР В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р В РЎвЂР РЋРІР‚С™Р В РЎвЂўР В РЎвЂ“).
                continue
            gross = (cur - o['buy_price']) * o['qty']
            buy_fee = o['total_cost'] * TRADE_FEE_RATE
            sell_fee = cur * o['qty'] * TRADE_FEE_RATE
            net = gross - buy_fee - sell_fee
            forecast_map[code] = forecast_map.get(code, 0) + net

    result = {}
    prev_closes = tinkoff_prices.previous_closes(instruments)
    # Р В Р’В Р В Р’ВµР В Р’В°Р В Р’В»Р В РЎвЂР В Р’В·Р В РЎвЂўР В Р вЂ Р В Р’В°Р В Р вЂ¦Р В РЎвЂў Р В Р’В·Р В Р’В° Р В Р вЂ Р РЋР С“Р РЋР вЂ№ Р В РЎвЂР РЋР С“Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂР РЋР вЂ№ Р Р†Р вЂљРІР‚Сњ Р В Р вЂ¦Р РЋРЎвЂњР В Р’В¶Р В Р вЂ¦Р В РЎвЂў Р В РЎвЂќР В РЎвЂўР В Р’В»Р В РЎвЂўР В Р вЂ¦Р В РЎвЂќР В Р’Вµ Р вЂ™Р’В«Р В РІР‚в„ўР РЋР С“Р В Р’ВµР В РЎвЂ“Р В РЎвЂўР вЂ™Р’В» (Р В Р вЂ Р В Р’ВµР РЋР С“Р РЋР Р‰ Р РЋР вЂљР В Р’ВµР В Р’В°Р В Р’В»Р В РЎвЂР В Р’В·Р В РЎвЂўР В Р вЂ Р В Р’В°Р В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р В РІвЂћвЂ“
    # Р РЋР вЂљР В Р’ВµР В Р’В·Р РЋРЎвЂњР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™ + Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋРЎвЂњР РЋРІР‚В°Р В Р’В°Р РЋР РЏ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР В РЎвЂўР РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В РЎвЂќР В Р’В° Р В РЎвЂ”Р В РЎвЂўР В Р’В·Р В РЎвЂР РЋРІР‚В Р В РЎвЂР В РЎвЂ), Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р РЋРІР‚С™Р В РЎвЂўР В Р’В»Р РЋР Р‰Р В РЎвЂќР В РЎвЂў Р В Р’В·Р В Р’В° Р РЋРІР‚С›Р В РЎвЂР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р РЋР вЂљ.
    realized_all = {p['security_code']: p['net_profit']
                    for p in get_trade_profit(None, None, to_dmy(date_to), broker)}
    for code, val in forecast_map.items():
        result[code] = {
            'forecast': round(val, 2),
            'current_price': price_map.get(code, 0),
            'prev_close': prev_closes.get(code),
            'realized_all': round(realized_all.get(code, 0), 2),
            'net_profit': None,  # Р В Р’В·Р В Р’В°Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ¦Р В Р’В° Р В РЎвЂќР В Р’В»Р В РЎвЂР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’Вµ Р В РЎвЂР В Р’В· HTML
        }
    return jsonify(result), 200


@flask_app.route('/portfolio-growth')
def portfolio_growth_view():
    """Р В Р’В Р В РЎвЂўР РЋР С“Р РЋРІР‚С™ Р В РЎвЂ”Р В РЎвЂўР РЋР вЂљР РЋРІР‚С™Р РЋРІР‚С›Р В Р’ВµР В Р’В»Р РЋР РЏ Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂ“Р В РЎвЂўР В РўвЂР В Р’В°Р В РЎВ: Р РЋР С“Р В Р вЂ¦Р В РЎвЂР В РЎВР В РЎвЂќР В РЎвЂ Р В Р’В°Р В РЎвЂќР РЋРІР‚С™Р В РЎвЂР В Р вЂ Р В РЎвЂўР В Р вЂ  Р В РЎвЂР В Р’В· Р В РЎвЂўР РЋРІР‚С™Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™Р В РЎвЂўР В Р вЂ , TWR, MCFTR, USD."""
    try:
        data = portfolio_growth.build()
        data['invested'] = portfolio_growth.invested_summary()
        try:
            data['portfolio_now'] = portfolio_growth.current_portfolio_summary(data['invested'])
        except Exception as exc:  # noqa: BLE001 — блок не должен ломать страницу
            flask_app.logger.warning('portfolio_now: %s', exc)
        # Сценарий «закрыть всё по таргетам»: прирост стоимости и XIRR при нём
        try:
            targets = get_price_targets()
            inst = get_instrument_summary(None, '', '', 'all')
            db_prices = get_current_prices()
            pi = _position_instruments(get_open_trades(None, '', '', 'all'),
                                       get_quik_positions('all'), get_my_instruments())
            prices, _src = _effective_prices(db_prices, pi, False)
            pm = {p['sec_code']: p['price'] for p in prices}
            uplift = 0.0
            for i in inst or []:
                target = targets.get(i['security_code'])
                price = pm.get(i['security_code']) or 0
                if target and price:
                    uplift += (i['qty'] or 0) * (target - price)
            inv = data['invested']
            inv['value_at_target'] = round((inv.get('value') or 0) + uplift, 2)
            inv['uplift'] = round(uplift, 2)
            # Текущая переоценка открытых позиций и «прочее» (комиссии, налоги,
            # расхождения данных) — чтобы сверка не прятала всё в одну цифру.
            inv['unrealized'] = round(sum((i['qty'] or 0) * (pm.get(i['security_code']) or 0)
                                          - (i['total_cost'] or 0)
                                          for i in inst or [] if pm.get(i['security_code'])), 2)
            inv['other'] = round((inv.get('value') or 0)
                                 - (inv.get('net_invested') or 0)
                                 - (inv.get('income') or 0)
                                 - (inv.get('trading') or 0)
                                 - inv['unrealized'], 2)
            inv['xirr_target'] = portfolio_growth.xirr_for_value(inv['value_at_target'])
            inv['xirr_target_period'] = portfolio_growth.xirr_for_value(
                inv['value_at_target'], inv.get('period_start'), inv.get('period_start_value'))
        except Exception as exc:  # noqa: BLE001 — сценарий не должен ломать страницу
            flask_app.logger.warning('target scenario: %s', exc)
    except Exception as exc:  # noqa: BLE001 Р Р†Р вЂљРІР‚Сњ Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚В Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р В РўвЂР В РЎвЂўР В Р’В»Р В Р’В¶Р В Р вЂ¦Р В Р’В° Р В РЎвЂ”Р В Р’В°Р В РўвЂР В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р РЋРІР‚В Р В Р’ВµР В Р’В»Р В РЎвЂР В РЎвЂќР В РЎвЂўР В РЎВ
        flask_app.logger.warning('portfolio_growth: %s', exc)
        data = {'years': [], 'series': [], 'snapshots': [], 'transfers': 0.0, 'invested': {},
                'benchmark': portfolio_growth.BENCHMARK, 'usd': portfolio_growth.USD_INSTRUMENT,
                'start': '', 'end': '', 'error': str(exc)}
    return render_template('portfolio_growth.html', data=data,
                           manual_flows=get_manual_flows())


@flask_app.route('/screener')
def screener_view():
    """Р В Р Р‹Р В РЎвЂќР РЋР вЂљР В РЎвЂР В Р вЂ¦Р В Р’ВµР РЋР вЂљ Р В Р’В°Р В РЎвЂќР РЋРІР‚В Р В РЎвЂР В РІвЂћвЂ“ Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂўР В Р’В±Р РЋР вЂ°Р РЋРІР‚ВР В РЎВР В Р вЂ¦Р В РЎвЂўР В РЎВР РЋРЎвЂњ Р В Р’В°Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂР В Р’В·Р РЋРЎвЂњ Р В РЎвЂўР В Р’В±Р В Р’ВµР В Р’В·Р В Р’В»Р В РЎвЂР РЋРІР‚РЋР В Р’ВµР В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р РЋРІР‚В¦ Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂўР В РЎвЂќ."""
    return render_template('screener.html',
                           status=screener.collector_status(),
                           signals=screener.SIGNAL_LABELS,
                           universe=screener.universe_snapshot())


@flask_app.route('/api/screener')
def api_screener():
    """Р В РЎС™Р В Р’ВµР РЋРІР‚С™Р РЋР вЂљР В РЎвЂР В РЎвЂќР В РЎвЂ Р РЋР С“Р В РЎвЂќР РЋР вЂљР В РЎвЂР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°. Р В РЎСџР В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР РЋРІР‚в„–: window, min_turnover, signal, limit."""
    window = request.args.get('window', 'session')
    try:
        min_turnover = float(request.args.get('min_turnover', 0) or 0)
    except ValueError:
        min_turnover = 0.0
    limit = max(1, min(request.args.get('limit', 200, type=int), 500))
    wanted = {s.strip() for s in (request.args.get('signal') or '').split(',') if s.strip()}

    rows = screener.compute_metrics(window=window, min_turnover=min_turnover)
    if wanted:
        rows = [r for r in rows if r['signal'] in wanted]

    # Р В РІР‚в„ўР В РЎвЂўР В Р’В»Р В Р’В°Р РЋРІР‚С™Р В РЎвЂР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂўР РЋР С“Р РЋРІР‚С™Р РЋР Р‰ Р РЋР С“Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р В Р’ВµР В РЎВ Р В РЎвЂ”Р В РЎвЂў Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В РЎвЂќР В Р’В°Р В РЎВ Р РЋРІР‚С™Р В РЎвЂўР В РЎвЂ“Р В РЎвЂў Р В Р’В¶Р В Р’Вµ Р В РЎвЂўР В РЎвЂќР В Р вЂ¦Р В Р’В°: Р В РЎвЂўР В РўвЂР В Р вЂ¦Р В Р’В° SQL-Р В Р вЂ Р РЋРІР‚в„–Р В Р’В±Р В РЎвЂўР РЋР вЂљР В РЎвЂќР В Р’В° Р В Р вЂ¦Р В Р’В°
    # Р В Р вЂ Р В Р’ВµР РЋР С“Р РЋР Р‰ Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВ, Р В РЎвЂ”Р В РЎвЂўР РЋР РЉР РЋРІР‚С™Р В РЎвЂўР В РЎВР РЋРЎвЂњ Р РЋРІР‚С™Р В Р’В°Р В Р’В±Р В Р’В»Р В РЎвЂР РЋРІР‚В Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В РЎвЂР В Р вЂ¦Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎВР В РЎвЂўР В Р’В·Р В РЎвЂР РЋРІР‚С™Р РЋР Р‰.
    try:
        vol_from, vol_to, _ = screener._window_bounds(window)
        vols = volatility.universe(vol_from, vol_to, interval=1)
    except Exception:
        vols = {}
    # Р В Р’В¤Р В РЎвЂўР В Р вЂ¦Р В РЎвЂўР В Р вЂ Р РЋРІР‚в„–Р В РІвЂћвЂ“ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В Р’ВµР РЋР С“Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ : Р В РЎвЂўР В Р вЂ¦ Р В Р’В¶Р В Р’Вµ Р В РЎвЂ”Р В РЎвЂўР В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™ Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В» Р В Р вЂ  Р В РІР‚ВР В РІР‚Сњ.
    try:
        _, signals_at = signals_cache.snapshot()
    except Exception:
        signals_at = 0.0

    # Р В Р’ВР В РЎВР В Р’ВµР В Р вЂ¦Р В Р’В° Р Р†Р вЂљРІР‚Сњ Р В РЎвЂ”Р В РЎвЂў Р В Р’В±Р РЋРЎвЂњР В РЎВР В Р’В°Р В РЎвЂ“Р В Р’В°Р В РЎВ Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВР В Р’В° Р РЋР С“Р В РЎвЂќР РЋР вЂљР В РЎвЂР В Р вЂ¦Р В Р’ВµР РЋР вЂљР В Р’В°. Р В РІР‚вЂњР РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В» Р РЋРІР‚В¦Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚С™ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р РЋРІР‚в„– Р В РЎвЂ Р В РЎвЂ”Р В РЎвЂў
    # Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В°Р В РЎВ, Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂќР РЋР вЂљР РЋРІР‚в„–Р РЋРІР‚С™Р РЋРІР‚в„–Р В РЎВ Р В Р вЂ¦Р В Р’В° Р В РЎвЂ“Р РЋР вЂљР В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќР В Р’Вµ, Р В Р вЂ¦Р В РЎвЂў Р В Р вЂ  Р РЋР РЉР РЋРІР‚С™Р В РЎвЂўР В РІвЂћвЂ“ Р РЋРІР‚С™Р В Р’В°Р В Р’В±Р В Р’В»Р В РЎвЂР РЋРІР‚В Р В Р’Вµ Р В РЎвЂўР В Р вЂ¦Р В РЎвЂ Р В Р’В»Р В РЎвЂР РЋРІвЂљВ¬Р В Р вЂ¦Р В РЎвЂР В Р’Вµ.
    names = {}
    try:
        names = {inst['ticker']: (inst.get('name') or '')
                 for inst in screener.universe_snapshot() if inst.get('selected')}
    except Exception:
        pass
    for row in rows:
        names[row['ticker']] = row.get('name') or names.get(row['ticker'], '')

    # Р В Р Р‹Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™Р РЋРІР‚РЋР В РЎвЂР В РЎвЂќР В РЎвЂ Р В РЎвЂ Р РЋРІР‚С™Р В Р’В°Р В Р’В±Р В Р’В»Р В РЎвЂР РЋРІР‚В Р В Р’В° Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ  Р Р†Р вЂљРІР‚Сњ Р В РЎвЂР В Р’В· Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В»Р В Р’В°, Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р В РЎвЂР В Р’В· Р РЋРІР‚С™Р В Р’ВµР В РЎвЂќР РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР В РЎвЂ“Р В РЎвЂў Р РЋР вЂљР В Р’В°Р РЋР С“Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™Р В Р’В°:
    # Р РЋР С“Р РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™Р РЋРЎвЂњР РЋР С“ (Р В РЎвЂ”Р РЋР вЂљР В РЎвЂР В Р вЂ¦Р РЋР РЏР РЋРІР‚С™ / Р В РЎвЂўР РЋРІР‚С™Р РЋР С“Р В Р’ВµР РЋР РЏР В Р вЂ¦) Р В РЎвЂ Р В Р вЂ Р РЋР вЂљР В Р’ВµР В РЎВР РЋР РЏ Р В РЎвЂ”Р В РЎвЂўР РЋР РЏР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќР РЋР С“Р В РЎвЂР РЋР вЂљР РЋРЎвЂњР РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В РЎвЂўР В РўвЂР В РЎвЂР В Р вЂ¦ Р РЋР вЂљР В Р’В°Р В Р’В·.
    day_today = datetime.now(screener.MSK).strftime('%Y-%m-%d')
    try:
        journal_counts = {ticker: info for ticker, info
                          in signal_journal.counts(day=day_today).items()
                          if ticker in names}
        journal_rows = [sig for sig in signal_journal.rows(day=day_today, limit=1000)
                        if sig['ticker'] in names]
    except Exception:
        journal_counts, journal_rows = {}, []
    for row in rows:
        info = journal_counts.get(row['ticker'], {})
        row['signal_count'] = int(info.get('count', 0))
        row['signal_taken'] = int(info.get('taken', 0))
        row['signal_skipped'] = int(info.get('skipped', 0))
        row['signal_last'] = info.get('last')
        row['signal_kinds'] = info.get('kinds', [])

    for row in rows:
        vol = vols.get(row['ticker'], {})
        row['vol_day_pct'] = vol.get('sigma_day_pct', 0.0)
        row['vol_range_rub'] = vol.get('range_rub', 0.0)
        row['vol_atr_rub'] = vol.get('atr_rub', 0.0)
        row['vol_range_pct'] = vol.get('range_pct', 0.0)

    # Р В РЎв„ўР В Р’В°Р РЋРІР‚РЋР В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р вЂ Р В РЎвЂў Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋРІвЂљВ¬Р В Р’В»Р РЋРІР‚в„–Р РЋРІР‚В¦ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ  Р В РЎвЂ Р В РўвЂР В Р’ВµР В РІвЂћвЂ“Р РЋР С“Р РЋРІР‚С™Р В Р вЂ Р РЋРЎвЂњР РЋР вЂ№Р РЋРІР‚В°Р В РЎвЂР В Р’Вµ Р В РЎвЂР В Р вЂ¦Р В РўвЂР В РЎвЂР В Р вЂ Р В РЎвЂР В РўвЂР РЋРЎвЂњР В Р’В°Р В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р В РЎвЂ”Р В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР РЋРІР‚в„–.
    try:
        quality = adaptive.quality_map()
    except Exception:
        quality = {}
    for row in rows:
        info = quality.get(row['ticker']) or {}
        row['quality_trades'] = int(info.get('trades', 0))
        row['quality_win_rate'] = float(info.get('win_rate', 0.0))
        row['quality_pf'] = float(info.get('profit_factor', 0.0))
        row['quality_net'] = float(info.get('net', 0.0))
        try:
            row['adaptive_params'] = adaptive.summary(row['ticker'])
        except Exception:
            row['adaptive_params'] = {}

    # Р В РІР‚ВР РЋРЎвЂњР В РЎВР В Р’В°Р В РЎвЂ“Р В РЎвЂ Р РЋР С“ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В Р’В°Р В РЎВР В РЎвЂ Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р В Р’ВµР В РЎвЂ“Р В РЎвЂР В РЎвЂ Р Р†Р вЂљРІР‚Сњ Р В Р вЂ¦Р В Р’В°Р В Р вЂ Р В Р’ВµР РЋР вЂљР РЋРІР‚В¦Р РЋРЎвЂњ, Р В Р вЂ Р В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р РЋР вЂљР В РЎвЂ Р В РЎвЂ“Р РЋР вЂљР РЋРЎвЂњР В РЎвЂ”Р В РЎвЂ”Р РЋРІР‚в„– Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂўР РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В РЎвЂќР В Р’Вµ.
    # Р В Р Р‹Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’В°Р В Р’В»Р В Р’В° Р В РЎвЂ”Р РЋР вЂљР В РЎвЂР В Р вЂ¦Р РЋР РЏР РЋРІР‚С™Р РЋРІР‚в„–Р В Р’Вµ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р РЋРІР‚в„– (Р В РЎвЂР РЋРІР‚В¦ Р В РЎВР В РЎвЂўР В Р’В¶Р В Р вЂ¦Р В РЎвЂў Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂ“Р В РЎвЂўР В Р вЂ Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰), Р В РЎвЂ”Р В РЎвЂўР РЋРІР‚С™Р В РЎвЂўР В РЎВ Р В РЎвЂўР РЋР С“Р РЋРІР‚С™Р В Р’В°Р В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ.
    rows.sort(key=lambda r: (-r.get('signal_taken', 0),
                             -r.get('signal_count', 0), -r.get('score', 0)))

    # Р В РЎС›Р В Р’В°Р В Р’В±Р В Р’В»Р В РЎвЂР РЋРІР‚В Р В Р’В° Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ : Р В РЎвЂќР В Р’В°Р В Р’В¶Р В РўвЂР РЋРІР‚в„–Р В РІвЂћвЂ“ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В» Р РЋР С“Р В РЎвЂў Р РЋР С“Р В Р вЂ Р В РЎвЂўР В РЎвЂР В РЎВ Р В Р вЂ Р РЋР вЂљР В Р’ВµР В РЎВР В Р’ВµР В Р вЂ¦Р В Р’ВµР В РЎВ Р В РЎвЂ”Р В РЎвЂўР РЋР РЏР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р В РЎвЂ Р РЋР С“Р РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™Р РЋРЎвЂњР РЋР С“Р В РЎвЂўР В РЎВ,
    # Р В Р’В·Р В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќР РЋР С“Р В РЎвЂР РЋР вЂљР В РЎвЂўР В Р вЂ Р В Р’В°Р В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р В РЎВ Р В Р вЂ  Р В РЎВР В РЎвЂўР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™ Р В Р’В·Р В Р’В°Р В РЎвЂ”Р В РЎвЂР РЋР С“Р В РЎвЂ (Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В» append-only).
    signal_rows = [dict(sig, name=names.get(sig['ticker'], '')) for sig in journal_rows]

    return jsonify({
        'window': rows[0]['window'] if rows else window,
        'count': len(rows),
        'rows': rows[:limit],
        'status': screener.collector_status(),
        'signals_at': signals_at,
        'signals_total': sum(r.get('signal_count', 0) for r in rows),
        'signals': signal_rows[-300:],
        'signals_count': sum(c.get('count', 0) for c in journal_counts.values()),
        'signals_taken': sum(c.get('taken', 0) for c in journal_counts.values()),
    })


@flask_app.route('/api/screener/status')
def api_screener_status():
    return jsonify(screener.collector_status())


@flask_app.route('/api/screener/<ticker>')
def api_screener_instrument(ticker):
    """Р В РІР‚СњР В Р’ВµР РЋРІР‚С™Р В Р’В°Р В Р’В»Р В РЎвЂР В Р’В·Р В Р’В°Р РЋРІР‚В Р В РЎвЂР РЋР РЏ: Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР В РЎвЂР В РЎвЂќР В РЎвЂ, Р В Р’В»Р В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂўР В РЎвЂќ Р В РЎвЂ Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р В Р’В° Р В РЎвЂ”Р В РЎвЂў Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В Р’В°Р В РЎВ."""
    window = request.args.get('window', 'session')
    limit = max(10, min(request.args.get('limit', 150, type=int), 500))
    detail = screener.instrument_detail(ticker, window=window, limit=limit)
    if detail is None:
        return jsonify({'error': 'Р В Р’ВР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™ Р В Р вЂ¦Р В Р’Вµ Р В Р вЂ¦Р В Р’В°Р В РІвЂћвЂ“Р В РўвЂР В Р’ВµР В Р вЂ¦ Р В Р вЂ  Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВР В Р’Вµ'}), 404
    return jsonify(detail)


@flask_app.route('/api/screener/refresh-universe', methods=['POST'])
def api_screener_refresh_universe():
    """Р В РЎСџР В Р’ВµР РЋР вЂљР В Р’ВµР РЋР С“Р В РЎвЂўР В Р’В±Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВ Р РЋРІР‚С™Р В РЎвЂўР В РЎвЂ”-N Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂўР В Р’В±Р В РЎвЂўР РЋР вЂљР В РЎвЂўР РЋРІР‚С™Р РЋРЎвЂњ (Р В Р вЂ  Р РЋРІР‚С›Р В РЎвЂўР В Р вЂ¦Р В Р’Вµ, Р В РўвЂР В РЎвЂў Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р РЋРІР‚в„–)."""
    if not screener.is_enabled():
        return jsonify({'error': 'Р В Р Р‹Р В РЎвЂќР РЋР вЂљР В РЎвЂР В Р вЂ¦Р В Р’ВµР РЋР вЂљ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂќР В Р’В»Р РЋР вЂ№Р РЋРІР‚РЋР В Р’ВµР В Р вЂ¦: Р В Р’В·Р В Р’В°Р В РўвЂР В Р’В°Р В РІвЂћвЂ“Р РЋРІР‚С™Р В Р’Вµ TINKOFF_TOKEN'}), 400
    if not screener.request_universe_refresh():
        return jsonify({'ok': False, 'message': 'Р В РЎвЂєР В Р’В±Р В Р вЂ¦Р В РЎвЂўР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’Вµ Р РЋРЎвЂњР В Р’В¶Р В Р’Вµ Р В Р вЂ Р РЋРІР‚в„–Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В Р вЂ¦Р РЋР РЏР В Р’ВµР РЋРІР‚С™Р РЋР С“Р РЋР РЏ'}), 202
    return jsonify({'ok': True, 'message': 'Р В РЎвЂєР В Р’В±Р В Р вЂ¦Р В РЎвЂўР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’Вµ Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВР В Р’В° Р В Р’В·Р В Р’В°Р В РЎвЂ”Р РЋРЎвЂњР РЋРІР‚В°Р В Р’ВµР В Р вЂ¦Р В РЎвЂў'}), 202



# Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ Р В РІР‚СљР РЋР вЂљР В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќ Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В° Р В РЎвЂ Р В Р’В±Р РЋР РЉР В РЎвЂќР РЋРІР‚С™Р В Р’ВµР РЋР С“Р РЋРІР‚С™ Р Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљР Р†РІР‚СњР вЂљ


@flask_app.route('/chart')
@flask_app.route('/chart/<ticker>')
def chart_view(ticker=None):
    """Р В РІР‚СљР РЋР вЂљР В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќ Р РЋР С“Р В Р вЂ Р В Р’ВµР РЋРІР‚РЋР В Р’ВµР В РІвЂћвЂ“ Р РЋР С“ Р В РЎВР В Р’В°Р РЋР вЂљР В РЎвЂќР В Р’ВµР РЋР вЂљР В Р’В°Р В РЎВР В РЎвЂ Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂўР В РЎвЂќ Р В РЎвЂ Р В РЎвЂ”Р В Р’В°Р В Р вЂ¦Р В Р’ВµР В Р’В»Р РЋР Р‰Р РЋР вЂ№ Р В Р’В±Р РЋР РЉР В РЎвЂќР РЋРІР‚С™Р В Р’ВµР РЋР С“Р РЋРІР‚С™Р В Р’В°."""
    if not ticker:
        rows = screener.universe_snapshot()
        first = next((r['ticker'] for r in rows if r['selected']), 'SBER')
        return redirect(url_for('chart_view', ticker=first))
    return render_template('chart.html',
                           ticker=ticker.upper(),
                           strategies=strategy_levels.catalog())


def _chart_range():
    range_key = request.args.get('range', '3d')
    interval = request.args.get('interval', 5, type=int)
    if interval not in chartdata.INTERVALS:
        interval = 5
    from_ns, to_ns, _ = chartdata.resolve_range(range_key)
    return from_ns, to_ns, range_key, interval


@flask_app.route('/api/chart/<ticker>')
def api_chart(ticker):
    """Р В Р Р‹Р В Р вЂ Р В Р’ВµР РЋРІР‚РЋР В РЎвЂ, Р В РЎвЂўР В Р’В±Р РЋР вЂ°Р РЋРІР‚ВР В РЎВ, Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р РЋРІР‚С™Р В Р’В° Р В РЎвЂ VWAP Р В Р’В·Р В Р’В° Р В Р вЂ Р РЋРІР‚в„–Р В Р’В±Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р В РІвЂћвЂ“ Р В РўвЂР В РЎвЂР В Р’В°Р В РЎвЂ”Р В Р’В°Р В Р’В·Р В РЎвЂўР В Р вЂ¦."""
    from_ns, to_ns, range_key, interval = _chart_range()
    try:
        data = chartdata.series(ticker, from_ns, to_ns, interval)
        data['volatility'] = volatility.metrics(ticker, from_ns, to_ns, interval)
    except chartdata.ChartError as exc:
        return jsonify({'error': str(exc)}), 400
    data['range'] = range_key
    return jsonify(data)


@flask_app.route('/api/signals/<ticker>')
def api_signals(ticker):
    """Р В Р Р‹Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р РЋРІР‚в„– Р В Р вЂ¦Р В Р’В° Р В РЎвЂ”Р В РЎвЂўР В РЎвЂќР РЋРЎвЂњР В РЎвЂ”Р В РЎвЂќР РЋРЎвЂњ Р В РЎвЂ”Р В РЎвЂў Р РЋРЎвЂњР РЋР вЂљР В РЎвЂўР В Р вЂ Р В Р вЂ¦Р РЋР РЏР В РЎВ Р В Р’В·Р В Р’В° Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂ“Р В РЎвЂўР В Р вЂ Р РЋРІР‚в„–Р В Р’Вµ Р В РўвЂР В Р вЂ¦Р В РЎвЂ Р В РўвЂР В РЎвЂР В Р’В°Р В РЎвЂ”Р В Р’В°Р В Р’В·Р В РЎвЂўР В Р вЂ¦Р В Р’В°.

    Р В Р Р‹Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂќР В Р’В°Р В Р’В¶Р В РўвЂР В РЎвЂўР В РЎВР РЋРЎвЂњ Р В РўвЂР В Р вЂ¦Р РЋР вЂ№ Р В РЎвЂўР РЋРІР‚С™Р В РўвЂР В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂў Р В Р вЂ¦Р В Р’В° Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В Р вЂ¦Р РЋРІР‚в„–Р РЋРІР‚В¦ Р В Р’В±Р В Р’В°Р РЋР вЂљР В Р’В°Р РЋРІР‚В¦ (``app.signal_days``):
    Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В» Р В РўвЂР В Р вЂ¦Р РЋР РЏ X Р В РЎвЂўР В РўвЂР В РЎвЂР В Р вЂ¦Р В Р’В°Р В РЎвЂќР В РЎвЂўР В Р вЂ  Р В РЎвЂ”Р РЋР вЂљР В РЎвЂ Р В Р’В»Р РЋР вЂ№Р В Р’В±Р В РЎвЂўР В РЎВ Р В РўвЂР В РЎвЂР В Р’В°Р В РЎвЂ”Р В Р’В°Р В Р’В·Р В РЎвЂўР В Р вЂ¦Р В Р’Вµ Р В РЎвЂ Р РЋРІР‚С™Р В Р’В°Р В РІвЂћвЂ“Р В РЎВР РЋРІР‚С›Р РЋР вЂљР В Р’ВµР В РІвЂћвЂ“Р В РЎВР В Р’Вµ Р В РЎвЂ“Р РЋР вЂљР В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќР В Р’В°, Р В РЎвЂ”Р В РЎвЂўР РЋР РЉР РЋРІР‚С™Р В РЎвЂўР В РЎВР РЋРЎвЂњ
    Р В РЎвЂР РЋР С“Р РЋРІР‚С™Р В РЎвЂўР РЋР вЂљР В РЎвЂР РЋР вЂ№ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ  Р В РЎВР В РЎвЂўР В Р’В¶Р В Р вЂ¦Р В РЎвЂў Р РЋР С“Р РЋР вЂљР В Р’В°Р В Р вЂ Р В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р В РЎВР В Р’ВµР В Р’В¶Р В РўвЂР РЋРЎвЂњ Р В РўвЂР В Р вЂ¦Р РЋР РЏР В РЎВР В РЎвЂ Р В РЎвЂ Р В РЎвЂўР РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р В Р’ВµР В РЎвЂ“Р В РЎвЂР РЋР вЂ№.
    """
    from_ns, to_ns, range_key, _interval = _chart_range()
    payload = {k: request.args.get(k) for k in
               ('warmup_min', 'approach_pct', 'break_margin_pct', 'confirm_delta',
                'volume_factor', 'take_profit_pct', 'stop_loss_pct', 'max_hold_min')}
    payload = {k: v for k, v in payload.items() if v is not None}
    # Р В РЎСџР В РЎвЂў Р РЋРЎвЂњР В РЎВР В РЎвЂўР В Р’В»Р РЋРІР‚РЋР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋР вЂ№ Р Р†Р вЂљРІР‚Сњ Р В РЎвЂР В Р вЂ¦Р В РўвЂР В РЎвЂР В Р вЂ Р В РЎвЂР В РўвЂР РЋРЎвЂњР В Р’В°Р В Р’В»Р РЋР Р‰Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р В РЎвЂ”Р В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР РЋРІР‚в„– Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В°; Р РЋР РЏР В Р вЂ Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р В РЎвЂ”Р В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР РЋРІР‚в„– Р В Р вЂ 
    # Р В Р’В·Р В Р’В°Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋР С“Р В Р’Вµ (manual=1 Р В РЎвЂР В Р’В»Р В РЎвЂ Р В Р’В»Р РЋР вЂ№Р В Р’В±Р В РЎвЂўР В Р’Вµ Р В Р’В·Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’Вµ) Р В Р вЂ Р В РЎвЂќР В Р’В»Р РЋР вЂ№Р РЋРІР‚РЋР В Р’В°Р РЋР вЂ№Р РЋРІР‚С™ Р РЋР вЂљР РЋРЎвЂњР РЋРІР‚РЋР В Р вЂ¦Р В РЎвЂўР В РІвЂћвЂ“ Р РЋР вЂљР В Р’ВµР В Р’В¶Р В РЎвЂР В РЎВ.
    manual = request.args.get('manual') == '1' or bool(payload)
    signals, zones = signal_days.signals_for_range(
        ticker, from_ns, to_ns, payload if manual else None)
    if not manual:
        # Р В Р’ВР РЋР С“Р РЋРІР‚С™Р В РЎвЂўР РЋРІР‚РЋР В Р вЂ¦Р В РЎвЂР В РЎвЂќ Р В РЎвЂР РЋР С“Р РЋРІР‚С™Р В РЎвЂР В Р вЂ¦Р РЋРІР‚в„– Р Р†Р вЂљРІР‚Сњ Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В»: Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В» Р В РЎвЂ Р В Р’ВµР В РЎвЂ“Р В РЎвЂў Р РЋР С“Р РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™Р РЋРЎвЂњР РЋР С“ Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќР РЋР С“Р В РЎвЂР РЋР вЂљР РЋРЎвЂњР РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ Р В Р вЂ  Р В РЎВР В РЎвЂўР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™
        # Р В РЎвЂ”Р В РЎвЂўР РЋР РЏР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р В РЎвЂ Р В Р’В±Р В РЎвЂўР В Р’В»Р РЋР Р‰Р РЋРІвЂљВ¬Р В Р’Вµ Р В Р вЂ¦Р В Р’Вµ Р В РЎВР В Р’ВµР В Р вЂ¦Р РЋР РЏР РЋР вЂ№Р РЋРІР‚С™Р РЋР С“Р РЋР РЏ. Р В Р’В Р В Р’В°Р РЋР С“Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™ Р В Р вЂ Р РЋРІР‚в„–Р РЋРІвЂљВ¬Р В Р’Вµ Р В РЎВР В РЎвЂўР В РЎвЂ“ Р В РўвЂР В РЎвЂўР В Р’В±Р В Р’В°Р В Р вЂ Р В РЎвЂР РЋРІР‚С™Р РЋР Р‰ Р В Р вЂ¦Р В РЎвЂўР В Р вЂ Р РЋРІР‚в„–Р В Р’Вµ
        # Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В РЎвЂќР В РЎвЂ, Р В РЎвЂ”Р В РЎвЂўР РЋР РЉР РЋРІР‚С™Р В РЎвЂўР В РЎВР РЋРЎвЂњ Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р В Р’ВµР В РЎВ Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В» Р В РЎвЂ”Р В РЎвЂўР РЋР С“Р В Р’В»Р В Р’Вµ Р В Р вЂ¦Р В Р’ВµР В РЎвЂ“Р В РЎвЂў.
        try:
            logged = signal_journal.rows(
                ticker,
                from_ts=from_ns // 1_000_000_000 + 3 * 3600,
                to_ts=to_ns // 1_000_000_000 + 3 * 3600,
                limit=2000)
        except Exception:
            # Р В Р Р‹Р В Р’В±Р В РЎвЂўР В РІвЂћвЂ“ Р В Р’В¶Р РЋРЎвЂњР РЋР вЂљР В Р вЂ¦Р В Р’В°Р В Р’В»Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р В РўвЂР В РЎвЂўР В Р’В»Р В Р’В¶Р В Р’ВµР В Р вЂ¦ Р В Р’В»Р В РЎвЂР РЋРІвЂљВ¬Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р В РЎвЂ“Р РЋР вЂљР В Р’В°Р РЋРІР‚С›Р В РЎвЂР В РЎвЂќ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р В РЎвЂўР В Р вЂ  Р В РЎвЂР В Р’В· Р РЋР вЂљР В Р’В°Р РЋР С“Р РЋРІР‚РЋР РЋРІР‚ВР РЋРІР‚С™Р В Р’В°.
            logged = []
        if logged:
            signals = logged
    return jsonify({
        'ticker': ticker.upper(),
        'params': strategy_levels._resolve(payload),
        'signals': signals,
        'markers': strategy_levels.signal_markers(signals),
        'zones': [{'price': z['price'], 'low': z['low'], 'high': z['high'],
                   'side': z['side'], 'origin': z.get('origin')} for z in zones],
        'count': len(signals),
        'range_key': range_key,
    })


@flask_app.route('/api/levels/<ticker>')
def api_levels(ticker):
    """Р В РЎСџР РЋР вЂљР В РЎвЂўР РЋРІР‚С›Р В РЎвЂР В Р’В»Р РЋР Р‰ Р В РЎвЂўР В Р’В±Р РЋР вЂ°Р РЋРІР‚ВР В РЎВР В Р’В° Р В РЎвЂ”Р В РЎвЂў Р РЋРІР‚В Р В Р’ВµР В Р вЂ¦Р В Р’Вµ, Р В Р’В·Р В РЎвЂўР В Р вЂ¦Р РЋРІР‚в„– Р В РЎвЂ”Р В РЎвЂўР В РўвЂР В РўвЂР В Р’ВµР РЋР вЂљР В Р’В¶Р В РЎвЂќР В РЎвЂ/Р РЋР С“Р В РЎвЂўР В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋРІР‚С™Р В РЎвЂР В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦Р В РЎвЂР РЋР РЏ Р В РЎвЂ Р В Р вЂ Р В Р’ВµР РЋР вЂљР В РўвЂР В РЎвЂР В РЎвЂќР РЋРІР‚С™."""
    from_ns, to_ns, range_key, _ = _chart_range()
    try:
        buckets = int(request.args.get('buckets', 80))
    except (TypeError, ValueError):
        buckets = 80
    try:
        large = float(request.args.get('large_rub') or 0) or \
            screener.get_config().large_trade_rub
    except ValueError:
        large = screener.get_config().large_trade_rub
    try:
        days = max(0, min(int(request.args.get('days', 0) or 0), 180))
    except (TypeError, ValueError):
        days = 0
    try:
        data = levels.analyze(ticker, from_ns, to_ns, buckets=buckets, large_rub=large,
                              history_days=days)
    except levels.LevelsError as exc:
        return jsonify({'error': str(exc)}), 400
    data['range_key'] = range_key
    return jsonify(data)


@flask_app.route('/api/volatility/<ticker>')
def api_volatility(ticker):
    """Р В РІР‚в„ўР В РЎвЂўР В Р’В»Р В Р’В°Р РЋРІР‚С™Р В РЎвЂР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В РЎвЂўР РЋР С“Р РЋРІР‚С™Р РЋР Р‰ Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В°: Р В Р’В°Р В Р’В±Р РЋР С“Р В РЎвЂўР В Р’В»Р РЋР вЂ№Р РЋРІР‚С™Р В Р вЂ¦Р В Р’В°Р РЋР РЏ (Р Р†РІР‚С™Р вЂ¦) Р В РЎвЂ Р В РЎвЂўР РЋРІР‚С™Р В Р вЂ¦Р В РЎвЂўР РЋР С“Р В РЎвЂР РЋРІР‚С™Р В Р’ВµР В Р’В»Р РЋР Р‰Р В Р вЂ¦Р В Р’В°Р РЋР РЏ (%)."""
    from_ns, to_ns, _, interval = _chart_range()
    try:
        data = volatility.metrics(ticker, from_ns, to_ns, interval)
    except chartdata.ChartError as exc:
        return jsonify({'error': str(exc)}), 400
    return jsonify(data)


@flask_app.route('/api/chart/<ticker>/markers')
def api_chart_markers(ticker):
    """Р В РЎС™Р В Р’В°Р РЋР вЂљР В РЎвЂќР В Р’ВµР РЋР вЂљР РЋРІР‚в„– Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂўР В РЎвЂќ: Р В РЎвЂќР РЋР вЂљР РЋРЎвЂњР В РЎвЂ”Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂР В Р вЂ¦Р РЋРІР‚С™Р РЋРІР‚в„– Р В РЎвЂР В Р’В»Р В РЎвЂ Р В Р вЂ Р РЋР С“Р В Р’Вµ (Р РЋР С“ Р В РЎвЂўР В РЎвЂ“Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚РЋР В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’ВµР В РЎВ)."""
    from_ns, to_ns, _, _ = _chart_range()
    mode = request.args.get('mode', 'large')
    if mode not in ('large', 'all'):
        mode = 'large'
    try:
        min_value = float(request.args.get('min_value') or 0)
    except ValueError:
        min_value = 0.0
    if min_value <= 0:
        min_value = screener.get_config().large_trade_rub
    try:
        return jsonify(chartdata.markers(ticker, from_ns, to_ns, min_value, mode))
    except chartdata.ChartError as exc:
        return jsonify({'error': str(exc)}), 400


@flask_app.route('/api/chart/<ticker>/tape')
def api_chart_tape(ticker):
    from_ns, to_ns, _, _ = _chart_range()
    limit = max(10, min(request.args.get('limit', 100, type=int), 500))
    return jsonify({'items': chartdata.tape(ticker, from_ns, to_ns, limit)})


@flask_app.route('/api/backtest/scan', methods=['POST'])
def api_backtest_scan():
    """Р В РЎСџР РЋР вЂљР В РЎвЂўР В Р вЂ Р В Р’ВµР РЋР вЂљР В РЎвЂќР В Р’В° Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р В Р’ВµР В РЎвЂ“Р В РЎвЂР В РЎвЂ Р В РЎвЂ”Р В РЎвЂў Р РЋРЎвЂњР В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВР РЋРЎвЂњ: in-sample / out-of-sample.

    Р В РЎвЂєР РЋРІР‚С™Р В Р вЂ Р В Р’ВµР РЋРІР‚РЋР В Р’В°Р В Р’ВµР РЋРІР‚С™ Р В Р вЂ¦Р В Р’В° Р В Р вЂ Р В РЎвЂўР В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋР С“ Р вЂ™Р’В«Р РЋР РЉР РЋРІР‚С›Р РЋРІР‚С›Р В Р’ВµР В РЎвЂќР РЋРІР‚С™Р В РЎвЂР В Р вЂ Р В Р вЂ¦Р В Р’В° Р В Р’В»Р В РЎвЂ Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р В Р’ВµР В РЎвЂ“Р В РЎвЂР РЋР РЏР вЂ™Р’В», Р В Р’В° Р В Р вЂ¦Р В Р’Вµ Р вЂ™Р’В«Р РЋРІР‚РЋР РЋРІР‚С™Р В РЎвЂў Р В Р’В±Р РЋРІР‚в„–Р В Р’В»Р В РЎвЂў Р В РЎвЂ”Р В РЎвЂў Р В РЎвЂўР В РўвЂР В Р вЂ¦Р В РЎвЂўР В РІвЂћвЂ“
    Р В Р’В±Р РЋРЎвЂњР В РЎВР В Р’В°Р В РЎвЂ“Р В Р’ВµР вЂ™Р’В»: Р В РЎвЂўР В РўвЂР В РЎвЂР В Р вЂ¦ Р В Р вЂ¦Р В Р’В°Р В Р’В±Р В РЎвЂўР РЋР вЂљ Р В РЎвЂ”Р В Р’В°Р РЋР вЂљР В Р’В°Р В РЎВР В Р’ВµР РЋРІР‚С™Р РЋР вЂљР В РЎвЂўР В Р вЂ  Р В Р вЂ¦Р В Р’В° Р В Р вЂ Р РЋР С“Р РЋРІР‚ВР В РЎВ Р В РЎвЂ”Р В Р’ВµР РЋР вЂљР В РЎвЂР В РЎвЂўР В РўвЂР В Р’Вµ, Р РЋР С“Р РЋР вЂљР В Р’В°Р В Р вЂ Р В Р вЂ¦Р В Р’ВµР В Р вЂ¦Р В РЎвЂР В Р’Вµ Р В РўвЂР В Р вЂ Р РЋРЎвЂњР РЋРІР‚В¦ Р В РЎвЂ”Р В РЎвЂўР В Р’В»Р В РЎвЂўР В Р вЂ Р В РЎвЂР В Р вЂ¦.
    """
    payload = request.get_json(silent=True) or {}
    strategy = payload.get('strategy') or strategy_levels.KEY
    range_key = payload.get('range') or 'today'
    try:
        interval = int(payload.get('interval', 1))
    except (TypeError, ValueError):
        interval = 1
    if interval not in chartdata.INTERVALS:
        interval = 1
    try:
        top = max(1, min(int(payload.get('top', 20)), 200))
    except (TypeError, ValueError):
        top = 20

    def _num(value, default):
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    notional = max(1000.0, _num(payload.get('notional'), 100_000.0))
    fee_pct = max(0.0, min(_num(payload.get('fee_pct'), 0.05), 1.0))
    try:
        split = min(0.9, max(0.1, _num(payload.get('split'), 0.6)))
    except (TypeError, ValueError):
        split = 0.6

    tickers = [t['ticker'] for t in screener.universe_snapshot() if t['selected']][:top]
    if not tickers:
        return jsonify({'error': 'Р В Р в‚¬Р В Р вЂ¦Р В РЎвЂР В Р вЂ Р В Р’ВµР РЋР вЂљР РЋР С“Р РЋРЎвЂњР В РЎВ Р В РЎвЂ”Р РЋРЎвЂњР РЋР С“Р РЋРІР‚С™ Р Р†Р вЂљРІР‚Сњ Р РЋР С“Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’В°Р В Р’В»Р В Р’В° Р РЋР С“Р В РЎвЂўР В Р’В±Р В Р’ВµР РЋР вЂљР В РЎвЂР РЋРІР‚С™Р В Р’Вµ Р В РўвЂР В Р’В°Р В Р вЂ¦Р В Р вЂ¦Р РЋРІР‚в„–Р В Р’Вµ'}), 400

    from_ns, to_ns, _ = chartdata.resolve_range(range_key)
    try:
        result = backtest.scan(tickers, from_ns, to_ns, strategy, payload.get('params'),
                               interval=interval, notional=notional, fee_pct=fee_pct,
                               split=split)
    except (chartdata.ChartError, backtest.BacktestError) as exc:
        return jsonify({'error': str(exc)}), 400
    return jsonify(result)


@flask_app.route('/api/backtest/<ticker>', methods=['POST'])
def api_backtest(ticker):
    """Р В РЎСџР РЋР вЂљР В РЎвЂўР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰ intraday-Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р РЋРІР‚С™Р В Р’ВµР В РЎвЂ“Р В РЎвЂР РЋР вЂ№ Р В РЎвЂ”Р В РЎвЂў Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В РЎвЂќР В Р’В°Р В РЎВ Р В РЎвЂР В Р вЂ¦Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР РЋРЎвЂњР В РЎВР В Р’ВµР В Р вЂ¦Р РЋРІР‚С™Р В Р’В°."""
    payload = request.get_json(silent=True) or {}
    strategy = payload.get('strategy') or strategy_levels.KEY
    range_key = payload.get('range') or request.args.get('range', 'today')
    interval = payload.get('interval', 1)
    try:
        interval = int(interval)
    except (TypeError, ValueError):
        interval = 1
    if interval not in chartdata.INTERVALS:
        interval = 1
    from_ns, to_ns, _ = chartdata.resolve_range(range_key)

    def _num(value, default):
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    notional = max(1000.0, _num(payload.get('notional'), 100_000.0))
    fee_pct = max(0.0, min(_num(payload.get('fee_pct'), 0.05), 1.0))
    try:
        if strategy == strategy_levels.KEY:
            # Р В РІР‚ВР РЋР РЉР В РЎвЂќР РЋРІР‚С™Р В Р’ВµР РЋР С“Р РЋРІР‚С™ Р РЋР С“Р РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р В Р’ВµР В РЎВ Р В РЎвЂ”Р В РЎвЂў Р В РўвЂР В Р вЂ¦Р РЋР РЏР В РЎВ Р В Р вЂ¦Р В Р’В° Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В РЎвЂќР В Р’В°Р РЋРІР‚В¦ Р Р†Р вЂљРІР‚Сњ Р РЋРІР‚С™Р В Р’В°Р В РЎвЂќ Р В Р’В¶Р В Р’Вµ, Р В РЎвЂќР В Р’В°Р В РЎвЂќ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В»Р РЋРІР‚в„–.
            # Р В Р’ВР В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’Вµ Р В Р вЂ¦Р В Р’В° 5-Р В РЎВР В РЎвЂР В Р вЂ¦Р РЋРЎвЂњР РЋРІР‚С™Р В РЎвЂќР В Р’В°Р РЋРІР‚В¦/3 Р В РўвЂР В Р вЂ¦Р РЋР РЏР РЋРІР‚В¦ Р В РЎвЂ”Р В РЎвЂўР РЋР вЂљР В РЎвЂўР В РЎвЂ“Р В РЎвЂ Р В РўвЂР РЋР вЂљР РЋРЎвЂњР В РЎвЂ“Р В РЎвЂР В Р’Вµ Р В РЎвЂ Р вЂ™Р’В«Р РЋР С“Р В РўвЂР В Р’ВµР В Р’В»Р В РЎвЂќР В РЎвЂР вЂ™Р’В» Р В РЎвЂР РЋР С“Р РЋРІР‚РЋР В Р’ВµР В Р’В·Р В Р’В°Р РЋР вЂ№Р РЋРІР‚С™,
            # Р РЋРІР‚В¦Р В РЎвЂўР РЋРІР‚С™Р РЋР РЏ Р РЋР С“Р В РЎвЂќР РЋР вЂљР В РЎвЂР В Р вЂ¦Р В Р’ВµР РЋР вЂљ Р В РЎвЂ”Р В РЎвЂўР В РЎвЂќР В Р’В°Р В Р’В·Р РЋРІР‚в„–Р В Р вЂ Р В Р’В°Р В Р’ВµР РЋРІР‚С™ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂР В Р вЂ¦Р РЋР РЏР РЋРІР‚С™Р РЋРІР‚в„–Р В РІвЂћвЂ“ Р РЋР С“Р В РЎвЂР В РЎвЂ“Р В Р вЂ¦Р В Р’В°Р В Р’В».
            days = signal_days.day_results(ticker, from_ns, to_ns,
                                           payload.get('params'))
            signals = sorted((s for d in days for s in d['signals']),
                             key=lambda s: s['time'])
            trades = sorted((t for d in days for t in d['trades']),
                            key=lambda t: t['exit_time'])
            running = 0.0
            equity = []
            for trade in trades:
                running += trade['pnl']
                equity.append({'time': trade['exit_time'], 'value': round(running, 2)})
            metrics = strategy_levels._metrics(trades, running, notional)
            metrics['skipped_rr'] = sum(
                (d.get('metrics') or {}).get('skipped_rr', 0) for d in days)
            last = days[-1] if days else None
            result = {
                'ticker': ticker.upper(),
                'strategy': strategy_levels.KEY,
                'label': strategy_levels.LABEL,
                'params': last['params'] if last else strategy_levels._resolve(payload.get('params')),
                'interval': 1,
                'notional': notional,
                'fee_pct': fee_pct,
                'bars': sum(d.get('bars', 0) for d in days),
                'signals': signals,
                'trades': trades,
                'equity': equity,
                'metrics': metrics,
                'stop_enabled': last.get('stop_enabled') if last else True,
                'no_stop_tickers': last.get('no_stop_tickers', []) if last else [],
                'markers': strategy_levels.signal_markers(signals),
            }
        else:
            result = backtest.run(ticker, from_ns, to_ns, strategy, payload.get('params'),
                                  interval=interval, notional=notional, fee_pct=fee_pct)
    except (chartdata.ChartError, backtest.BacktestError, levels.LevelsError) as exc:
        return jsonify({'error': str(exc)}), 400
    return jsonify(result)


TICKER_LOGO_COLORS = {
    'SBER': '#1a8c39', 'GAZP': '#0d5e8a', 'MOEX': '#7c3aed',
    'MTSS': '#e75614', 'AFKS': '#2563eb', 'RAGR': '#0891b2',
    'LQDT': '#d97706', 'RU000A10C3M0': '#be123c',
}

@flask_app.route('/api/logo/<ticker>', methods=['GET'])
def api_logo(ticker):
    """Generate ticker icon as SVG (local, no external calls)."""
    color = TICKER_LOGO_COLORS.get(ticker.upper(), '#6b7280')
    letter = ticker[0].upper() if ticker else '?'
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16">
        <rect width="16" height="16" rx="3" fill="{color}"/>
        <text x="8" y="11" text-anchor="middle" fill="white" font-size="9" font-weight="600" font-family="Arial,sans-serif">{letter}</text>
    </svg>'''
    return Response(svg, mimetype='image/svg+xml',
                    headers={'Cache-Control': 'public, max-age=86400'})


if __name__ == '__main__':
    init_db()
    flask_app.run(host='127.0.0.1', port=5000, debug=True)
